+using Microsoft.AspNetCore.Mvc;
+using Microsoft.EntityFrameworkCore;
+using Orders.Api.Domain;
+using Orders.Api.Infrastructure;
+
+namespace Orders.Api.Controllers;
+
+[ApiController]
+[Route("reports")]
+public sealed class ReportsController(OrdersDbContext db) : ControllerBase
+{
+    [HttpGet("cancelled")]
+    public async Task<IActionResult> Cancelled(CancellationToken cancellationToken)
+    {
+        var cancelled = await db.Orders
+            .Where(order => order.Status == OrderStatus.Cancelled)
+            .Select(order => new { order.Id, order.CustomerId, order.PlacedAt })
+            .ToListAsync(cancellationToken);
+
+        return Ok(cancelled);
+    }
+}

