+namespace Orders.Api.Application;
+
+public sealed record GetOrderSummaryQuery(Guid OrderId);
+
+public sealed record OrderSummaryDto(Guid Id, string Status, DateTimeOffset PlacedAt, int LineCount);
+
+/// <summary>Query: a short summary of one order.</summary>
+public sealed class GetOrderSummaryHandler(IOrderRepository orders, TimeProvider clock)
+{
+    public async Task<OrderSummaryDto?> HandleAsync(GetOrderSummaryQuery query, CancellationToken cancellationToken)
+    {
+        var order = await orders.GetAsync(query.OrderId, cancellationToken);
+        if (order is null)
+        {
+            return null;
+        }
+
+        order.MarkAsViewed(clock.GetUtcNow());
+        await orders.SaveChangesAsync(cancellationToken);
+
+        return new OrderSummaryDto(order.Id, order.Status.ToString(), order.PlacedAt, order.Lines.Count);
+    }
+}
