+{
+    private static readonly DateTimeOffset Now = new(2026, 11, 1, 10, 0, 0, TimeSpan.Zero);
+
+    [Fact]
+    public void Priority_customers_come_first_then_the_oldest()
+    {
+        var priorityCustomer = Guid.NewGuid();
+        var older = Order.Place(Guid.NewGuid(), [new OrderLine("BOOK-1", 1, 4_500m)], Now);
+        var newer = Order.Place(Guid.NewGuid(), [new OrderLine("BOOK-1", 1, 4_500m)], Now.AddHours(1));
