+/// <summary>Command: cancel several orders at once. Returns the IDs it did not find.</summary>
+public sealed class CancelOrdersHandler(IOrderRepository orders)
+{
+    public async Task<IReadOnlyList<Guid>> HandleAsync(CancelOrdersCommand command, CancellationToken cancellationToken)
+    {
+        var notFound = new List<Guid>();
+        foreach (var orderId in command.OrderIds)
+        {
+            var order = await orders.GetAsync(orderId, cancellationToken);
+            if (order is null)
+            {
+                notFound.Add(orderId);
+                continue;
+            }
+
+            order.Cancel();
+        }
+
+        await orders.SaveChangesAsync(cancellationToken);
+        return notFound;
+    }
+}
