+{
+    private static readonly DateTimeOffset Now = new(2026, 11, 1, 10, 0, 0, TimeSpan.Zero);
+
+    [Fact]
+    public void Placed_orders_priority_customers_first_then_the_oldest()
+    {
+        var priorityCustomer = Guid.NewGuid();
+        var older = Order.Place(Guid.NewGuid(), [new OrderLine("BOOK-1", 1, 4_500m)], Now);
+        var newer = Order.Place(Guid.NewGuid(), [new OrderLine("BOOK-1", 1, 4_500m)], Now.AddHours(1));
+        var cancelled = Order.Place(Guid.NewGuid(), [new OrderLine("BOOK-1", 1, 4_500m)], Now);
+        cancelled.Cancel();
+        var priority = Order.Place(priorityCustomer, [new OrderLine("BOOK-1", 1, 4_500m)], Now.AddHours(2));
+
+        var queue = WarehouseQueue.Arrange(
+            [newer, cancelled, older, priority],
+            customerId => customerId == priorityCustomer);
+
+        Assert.Equal([priority, older, newer], queue);
+    }
+}

